export function getUserByEmail(users: User[], email: string): User | null {
  return users.find((u) => u.email.toLowerCase() === email.trim().toLowerCase()) ?? null;
}

export function listOrders(orders: Order[], account: string, options: { includeCancelled?: boolean } = {}): Order[] {
  return orders.filter((o) => o.account === account && (options.includeCancelled || !o.cancelled));
}

export function estimateTokens(text: string | number): number {
  const bytes = typeof text === 'number' ? text : Buffer.byteLength(text, 'utf8');
  return Math.ceil(bytes / 4);
}
